using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Globalization;
using System.Collections.Generic;
public sealed class Favorite {public string kind="",id="",label="";}
internal sealed class SearchItem {internal string Kind,Id,Title,Detail,Body;internal int Score;}
internal static class GlobalSearch {
 internal static readonly string[] Kinds={"task","note","project","event","file","folder","mode","google","inbox"};
 internal static string KindName(string kind){return kind=="inbox"?"Idée à trier":kind=="task"?"Tâche":kind=="note"?"Note":kind=="project"?"Projet":kind=="event"?"Rendez-vous":kind=="file"?"Fichier joint":kind=="folder"?"Dossier":kind=="mode"?"Mode":"Google Drive";}
 internal static string Normalize(string text){var b=new StringBuilder();foreach(char c in (text??"").Normalize(NormalizationForm.FormD))if(CharUnicodeInfo.GetUnicodeCategory(c)!=UnicodeCategory.NonSpacingMark)b.Append(Char.ToLowerInvariant(c));return b.ToString().Normalize(NormalizationForm.FormC);}
 internal static IEnumerable<SearchItem> Index(Data d){foreach(var idea in d.inbox.Where(i=>!i.processed))yield return new SearchItem{Kind="inbox",Id=idea.id,Title=idea.title,Detail="Boîte de réception",Body=idea.body};foreach(var t in d.tasks)yield return new SearchItem{Kind="task",Id=t.id,Title=t.title,Detail=t.project+" · "+(t.status=="done"?"Terminée":t.status=="doing"?"En cours":"À faire")+(String.IsNullOrEmpty(t.due)?"":" · "+Schedule.Day(t.due).ToString("dd/MM/yyyy")),Body=t.notes};foreach(var n in d.pages.Where(n=>!n.trashed))yield return new SearchItem{Kind="note",Id=n.id,Title=n.title,Detail=String.IsNullOrEmpty(n.project)?"Page personnelle":n.project,Body=n.body};foreach(var name in d.settings.Projects.Concat(d.tasks.Select(t=>t.project)).Concat(d.pages.Where(n=>!n.trashed).Select(n=>n.project)).Concat(d.projectData.Select(p=>p.name)).Where(n=>!String.IsNullOrWhiteSpace(n)).Distinct()){var space=d.projectData.FirstOrDefault(candidate=>candidate.name==name);yield return new SearchItem{Kind="project",Id=name,Title=name,Detail="Espace de projet",Body=space==null?"":space.description};}foreach(var e in d.events)yield return new SearchItem{Kind="event",Id=e.id,Title=e.title,Detail=Schedule.Day(e.date).ToString("dd/MM/yyyy")+" · "+e.time+(String.IsNullOrEmpty(e.project)?"":" · "+e.project),Body=e.notes};foreach(var p in d.projectData)foreach(var f in p.files)yield return new SearchItem{Kind="file",Id=f.id,Title=f.name,Detail=p.name,Body=""};foreach(var file in d.googlePins)yield return new SearchItem{Kind="google",Id=file.id,Title=file.name,Detail=GoogleFiles.TypeName(file.mimeType),Body=""};foreach(var mode in d.modes)yield return new SearchItem{Kind="mode",Id=mode.id,Title=mode.name,Detail="Mode personnalisé · "+mode.actions.Count+" ouverture(s)",Body=mode.description+" "+String.Join(" ",mode.actions.Select(a=>a.label+" "+a.target))};foreach(var f in d.favorites.Where(f=>f.kind=="folder"))yield return new SearchItem{Kind="folder",Id=f.id,Title=f.label,Detail=f.id,Body=""};}
 internal static List<SearchItem> Find(Data d,string query,string kind){string q=Normalize(query).Trim();var tokens=q.Split(new[]{' ','\t','\r','\n'},StringSplitOptions.RemoveEmptyEntries);var result=new List<SearchItem>();foreach(var item in Index(d).Where(i=>String.IsNullOrEmpty(kind)||i.Kind==kind)){string title=Normalize(item.Title),haystack=title+" "+Normalize(item.Detail)+" "+Normalize(item.Body);if(!tokens.All(haystack.Contains))continue;item.Score=q.Length==0?0:title==q?100:title.StartsWith(q)?80:title.Contains(q)?60:tokens.All(title.Contains)?40:10;result.Add(item);}return result.OrderByDescending(i=>i.Score).ThenBy(i=>i.Title,StringComparer.CurrentCultureIgnoreCase).ThenBy(i=>i.Kind).ToList();}
 internal static SearchItem Resolve(Data d,Favorite f){return Index(d).FirstOrDefault(i=>i.Kind==f.kind&&i.Id==f.id);}
 internal static void Validate(Data d){if(d.favorites==null)d.favorites=new List<Favorite>();if(d.favorites.Count>200)throw new InvalidDataException("Limite : 200 favoris.");var seen=new HashSet<string>();d.favorites=d.favorites.Where(f=>f!=null&&Kinds.Contains(f.kind)&&!String.IsNullOrWhiteSpace(f.id)&&f.id.Length<=2048&&seen.Add(f.kind+"\n"+f.id)).ToList();foreach(var f in d.favorites){f.label=f.label??"";if(f.label.Length>200)f.label=f.label.Substring(0,200);if(f.kind=="folder"&&!Path.IsPathRooted(f.id))throw new InvalidDataException("Le chemin du dossier favori doit être absolu.");}}
 internal static void Test(string folder){var d=new Data();d.tasks.Add(new WorkTask{id="task",title="Réunion chantier",notes="préparer les plans",project="Travail",priority="Normale",status="todo",due=""});d.pages.Add(new NotePage{id="note",title="Plans",body="Réunion équipe",project="Travail"});d.pages.Add(new NotePage{id="trash",title="Réunion supprimée",body="",trashed=true});d.events.Add(new CalendarEvent{id="event",title="Visite chantier",date="2026-10-20",time="10:00",notes="métré"});ProjectData.Get(d,"Travail").files.Add(new ProjectFile{id=Guid.NewGuid().ToString(),name="Plan étage.pdf",extension=".pdf"});Store.Validate(d);if(Find(d,"reunion","").Count!=2||Find(d,"reunion plans","task").Count!=1||Find(d,"chantier","note").Count!=0||Find(d,"etage","file").Count!=1||Find(d,"metre","event").Count!=1)throw new Exception("Recherche multi-contenu / accents / filtres");d.favorites.Add(new Favorite{kind="task",id="task",label="Ancien nom"});d.favorites.Add(new Favorite{kind="task",id="task"});d.favorites.Add(new Favorite{kind="note",id="trash"});Store.Validate(d);if(d.favorites.Count!=2||Resolve(d,d.favorites[0]).Title!="Réunion chantier"||Resolve(d,d.favorites[1])!=null)throw new Exception("Résolution / doublons favoris");var s=new Store(Path.Combine(folder,"search"));s.Value=d;s.Save();s=new Store(s.Root);if(s.Value.favorites.Count!=2||Find(s.Value,"reunion","task").Count!=1)throw new Exception("Persistance recherche/favoris");s.Export(Path.Combine(folder,"search-export.json"));s.Value.favorites.Clear();s.Import(Path.Combine(folder,"search-export.json"));if(s.Value.favorites.Count!=2)throw new Exception("Import favoris");d.tasks.Clear();if(Resolve(d,d.favorites[0])!=null)throw new Exception("Référence supprimée");}
}
